import sys, subprocess
sys.path.insert(0, '.')
import pandas as pd, numpy as np
from score import *
from score_dots import *
from rules import *
from perbar import *
from exh_feats import *
from final_eval import P, exh_score


def run(script, args=()):
    return subprocess.run([sys.executable, script, *args], capture_output=True, text=True, cwd='.').stdout


F = pd.read_pickle('F_m5.pkl')
S = sample(F)
E = pd.read_pickle('E_m5.pkl')
Es = E[E.t.isin(SAMPLE)]
big = big_rule(S, **P['big'])
dot = dot_rule2(S, **P['dot'])
exh = exh_rule(Es, **P['exh'])
gtb = {g[0] for g in GT_BIG}
gtd = {g[0] for g in GT_DOT}


def agree(ours_bars, gt_bars):
    o = set(ours_bars)
    return (f"both non-empty {len(o & gt_bars)}, both empty {len(set(SAMPLE) - o - gt_bars)}, "
            f"ours-only {len(o - gt_bars)}, CORVEN-only {len(gt_bars - o)}")


out = []
w = out.append
w("# CORVEN M5 18/11/2026 - per-tick rule fitting log (results_iter.md)\n")
w("> Research note, rules for reading charts only. NOT a validated edge. Generated by `write_results.py` (re-run to refresh numbers). Prices: GC, UTC, tick 0.1.\n")
w("## 0. Calibration finding (changes earlier assumptions)\n")
w("- The old axis `3792-(y-12.7)/14.0` is wrong. Fitting the 26 horizontal grid lines gives **price = 3792.8228 - 0.0723329*y** (13.825 px per 1.0, so 1 tick = 1.38 px, max residual 0.05). With it, candle HIGHS in the image equal our data to 0.00-0.03: **there is NO price offset between CORVEN's chart and our data** (the earlier '+0.2-0.3' came from the wrong scale). `calib.py` prints the check. Wick-bottom pixels read ~0.33 low (stroke + triangle), ignore.")
w("- Old GT prices inside `fit_*.py` are therefore shifted by +0.1..+0.6 vs the new calibration. `gt_corven_m5.csv` supersedes them.")
w("- A dot is ~9.5 px = ~7 ticks tall; circle radii are 9-22 px (6-16 ticks). Pixel precision is about +-1 tick (1 px = 0.7 tick).\n")
w("## 1. Ground truth (`gt_corven_m5.csv`; built by `make_gt.py` from `extract_circles.py`, `extract_dots.py`, zoomed crops in `crops/`)\n")
w("- Circles: 25 (pink = Bid/sell side, light blue = Ask/buy side), fitted per bar with an alpha-blend model (centre x = bar centre; overlap = darker). Stacked pairs: 12:35 (r~22 at 3761.0 / 3760.0), 13:30 (small r10 at 3783.4 + large r20 at 3782.1), 13:50, 12:45, 13:00 (bottom pair). Low confidence: 12:35 pair, 13:00 bottom pair, 13:30 top small circle (it sits above the bar high, may be a halo of the orange triangle).")
w("- Dots: 16 blobs (red = Bid, blue = Ask). Dots overlap, so the true dot count is unobservable. Assumption: dot diameter 9.5 px, neighbouring dots 7 px apart => 33 dots (21-45 for 10-4 px spacing). Therefore dot results are reported at blob/pixel level (our dots are rendered as 9.5 px discs and merged exactly like CORVEN's) plus a dot count.")
w("- Exhaustion: tops 12:35, 12:45, 12:50, 13:30, 13:45 (5); bottoms 12:15, 13:10, 13:20, 13:40, 13:45, 13:50 (6), verified on zoomed crops.")
w("- Empty bars (rows `empty_*` in the CSV): circles absent in 11 of 26 bars, dots absent in 13, exhaustion-top absent in 21, exhaustion-bottom absent in 20.")
w("- 14:25 (forming bar) is excluded everywhere. CORVEN's bar-delta labels vs our bar delta: correlation 0.97 over the 26 bars (feeds agree except 12:50, 12:55, 14:05-14:20).\n")
w("## 2. Final rules (all per tick, no row grouping, baselines use only PREVIOUS bars)\n")
w("Notation per bar and per traded tick p: bid, ask, side=max(bid,ask), weak=min(bid,ask), trades(p)=number of prints. B20_m = mean over the previous 20 bars of (volume per traded level of that bar). B20_mx = mean over the previous 20 bars of (max side over the levels of that bar). Colour = dominant side (ask>bid -> blue, else red/pink).\n")
w("- **BIG circle** at tick p: `side(p) >= 0.5*B20_mx` AND side(p) is strictly the largest `side` within +-5 ticks of the same bar AND `side(p) >= 4*weak(p)` (weak floored at 1). Params: k=0.5, w=5 ticks, ratio=4.")
w("- **DOT** at tick p: `trades(p) >= 2.4*B20_m` AND side(p) is strictly the largest `side` within +-3 ticks. Params: k=2.4, w=3.")
w("- **EXHAUSTION** top (bottom) of a bar: `sum of Ask (Bid) over the 6 levels starting at the bar high (low) <= 1.1*B20_m` AND wick >= 3 ticks (wick = high - max(open,close), or min(open,close) - low). Params: n=6, k=1.1, wick=3.\n")
w("## 3. Scores on the 26 bars (ours vs CORVEN)\n")
for t in (1, 2, 4):
    r = score_big(big, t)
    d = score_dots(dot, t)
    w(f"- tol +-{t} ticks: BIG ours {r['n']} vs {r['gt']}: hit {r['hit']}, extra {r['extra']}, miss {r['miss']} | DOT ours {d['n']} dots / {d['blobs']} blobs vs ~{d['gt_est']} dots / {d['gt_blobs']} blobs: blob hit {d['blob_hit']}, blob extra {d['blob_extra']}, blob miss {d['blob_miss']}, our dots inside a CORVEN blob {d['dot_hit']}, pixel recall/precision/F1 {d['pix_rec']}/{d['pix_prec']}/{d['pix_f1']}")
x = exh_score(Es, exh)
w(f"- EXH (bar+side match): ours {x['n']} vs {x['gt']}: hit {x['hit']}, extra {x['extra']}, miss {x['miss']}, F1 {x['f1']}\n")
w("Bar-level agreement: BIG " + agree(big.datetime, gtb) + "; DOT " + agree(dot.datetime, gtd) + "\n")
w("## 4. Iteration log (all candidate rules re-scored by `iter_log.py`)\n")
w("Search space explored (scan_*.py, fit_all.py): metrics {side, vol, trades, |delta|, vol-trades, imbalance ratio, diagonal imbalance 200-800%, stack length 1-3}; baselines {previous 10/20/50/100-bar mean, median, p90, mean-of-bar-max, own-bar mean/max/total, share of bar volume, z-score, rank}; gates {local max +-1..8 ticks, ratio 1.5-5, floors 9/15, near-extreme}; window sums over +-1..4 ticks; 2-3 parameter combinations; top-N-by-feature tests (N=20/25/30) to compare feature quality at fixed count.\n")
w(run('iter_log.py'))
w("\nKey findings behind the iterations:\n")
w("- BIG: no single feature or small combination gets above 7-9 hits of 25 at +-2 ticks with 22-32 marks (random would give ~1-2). AUC of single cell features for 'cell is within 2 ticks of a CORVEN circle' is only 0.55-0.67; circle radius vs cell volume has Spearman 0.79 (circle SIZE is volume-driven, position is not tied to our local maxima). Colour = dominant side of the +-2-tick window agrees 22/25. A systematic vertical shift test (-8..+8 ticks) peaks at 0, so the position error is not a calibration problem. Untestable hypothesis: CORVEN's circles come from individual trade sizes (our `max_one_trade` column is 0).")
w("- DOT: AUC of cell features for 'inside a CORVEN dot blob' is 0.85 (bid/side/vol/trades); `trades` beats `vol` consistently. Pixel F1 saturates at 0.45-0.49 even at 43-48 dots; at 33-37 dots it is 0.40-0.43. CORVEN shows no dots in 13:00-13:20 and 13:30-13:55 although those bars are loud; no bar-level gate explaining it was found.")
w("- EXH: the summed soi-side volume over the 5-6 extreme levels has AUC 0.92-0.93 for 'CORVEN marked it' (smaller = marked). Recall 11/11 holds on a wide plateau (n=5: k 1.0-2.0, n=6: k 1.2-2.0, wick 2-3); only the number of extras changes (smoothly with k), so the law is not a lucky threshold.\n")
w("## 5. Per-bar comparison (final rules)\n")
w("BIG (`*` = matched within +-2 ticks, same colour; S = sell/pink, B = buy/light blue):\n```\n" + perbar_big(big) + "\n```\n")
w("DOT (price span of the rendered blob; S red, B blue):\n```\n" + perbar_dots(dot) + "\n```\n")
ex = []
for t in SAMPLE:
    o = ''.join(r.side for r in exh[exh.t == t].itertuples())
    g = ('T' if t in TOP else '') + ('B' if t in BOT else '')
    ex.append(f"{t[11:]} ours: {o or '-':3s} | CORVEN: {g or '-':3s} {'' if set(o) == set(g) else '<-- differs'}")
w("EXHAUSTION (T = orange top triangle, B = cyan bottom triangle):\n```\n" + "\n".join(ex) + "\n```\n")
w("## 6. Density and stability\n```\n" + run('density_stability.py') + "```\n")
w("Leave-half-out (fit on one half of the 26 bars, test on the other; 'final params' = the params above fitted on all 26 = in-sample reference):\n```\n" + run('leave_half_out.py') + "```\n")
open('results_iter.md', 'w', encoding='utf-8').write("\n".join(out))
print('written', len("\n".join(out)))
